mapper.select:
SELECT 
FROM notification_template
WHERE deleted = 0
AND id = #{templateId}
AND notification_code = #{notificationCode}
AND enabled = #{enabled}
ORDER BY notification_code, id

mapper.update:
UPDATE notification_template
SET enabled = #{enabled}, version = version + 1
WHERE id = #{templateId} AND deleted = 0 AND version = #{expectedVersion}

UPDATE notification_template
SET deleted = 1, version = version + 1
WHERE id = #{templateId} AND enabled = FALSE AND deleted = 0 AND version = #{expectedVersion}
